/** Folder holding the method inside the product's repository. */
export const METHOD_DIR = ".agentplugged";
export const METHOD_CONFIG_PATH = `${METHOD_DIR}/method.yaml`;
export const METHOD_GITIGNORE_PATH = `${METHOD_DIR}/.gitignore`;
/** Copy of the shipped model table, generated by `init`; the creator's values go in `method.yaml`. */
export const MODELS_PATH = `${METHOD_DIR}/models.yaml`;
export const METHOD_CONSTITUTION_PATH = `${METHOD_DIR}/AGENTS.md`;
export const ROOT_CONSTITUTION_PATH = "AGENTS.md";
/**
 * The detail of the constitution, generated, read on demand (corrections B; one file
 * per section): the `AGENTS.md` that the tools load at every request stays short.
 */
export const REFERENCE_DIR = `${METHOD_DIR}/reference`;
/** The single file the reference was: `sync` removes it when it generated it. */
export const REFERENCE_LEGACY_PATH = `${METHOD_DIR}/REFERENCE.md`;
/** The file of one section of the reference, by its short name (`reporting`, `tool-story`…). */
export const referenceFilePath = (name: string): string => `${REFERENCE_DIR}/${name}.md`;

/** Sub-folders of `.agentplugged/`, each kept in Git by a `.gitkeep`. */
export const METHOD_SUBDIRS = [
  "agents",
  "skills",
  "docs",
  "epics",
  "stories",
  "salle",
  "memory",
  "overrides",
  ".cache",
] as const;

/** Tool instruction files that may belong to the creator; `init` never creates them. */
export const POINTER_FILES = ["CLAUDE.md", "GEMINI.md"] as const;
